oxy_webhelp_navlinks = {"agent_cloud_RSC-d39307e61703":{"topics":[{"title":"Introduction to Agent Cloud","shortdesc":"<p class=\"shortdesc\">Describes what <span class=\"ph\">Agent Cloud<\/span> does, how it works, the key concepts and terms, and the features that are available in early access.<\/p>","href":"agent_cloud\/agent_cloud_overview.html","menu":{"hasChildren":false},"tocID":"tocId-d39307e61723","next":"tocId-d39307e61723"},{"title":"Get started with <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\">To start using <span class=\"ph\">Agent Cloud<\/span>, confirm the prerequisites, deploy a data         plane, connect your agents, verify the setup, and then add policies.<\/p>","href":"agent_cloud\/get_started_agent_cloud.html","attributes":{"data-id":"get_started_agent_cloud"},"menu":{"hasChildren":false},"tocID":"get_started_agent_cloud-d39307e61800","next":"get_started_agent_cloud-d39307e61800"},{"title":"Deploy your data plane","shortdesc":"<p class=\"shortdesc\">The <span class=\"ph\">Agent Cloud<\/span> data plane runs as a SaaS deployment that Rubrik         operates, or in your own AWS VPC or Azure VNet. Decide where it runs before you connect your         AI providers and agents.<\/p>","href":"agent_cloud\/agent_cloud_data_plane_provisioning.html","attributes":{"data-id":"agent_cloud_data_plane_provisioning"},"menu":{"hasChildren":false},"tocID":"agent_cloud_data_plane_provisioning-d39307e61875","next":"agent_cloud_data_plane_provisioning-d39307e61875"},{"title":"Connect your agents","shortdesc":"<p class=\"shortdesc\">A connection links <span class=\"ph\">Agent Cloud<\/span> to a source of agent activity, such as an         enterprise AI platform, a gateway that your custom agents use, or the endpoint detection         binary on employee devices.<\/p>","href":"agent_cloud\/configure_ai_connections.html","attributes":{"data-id":"configure_ai_connections"},"menu":{"hasChildren":false},"tocID":"configure_ai_connections-d39307e62039","next":"configure_ai_connections-d39307e62039"},{"title":"Discover and observe","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> builds an inventory of the agents, tools, identities, models,         and MCP servers in your environment, and records what each agent does, session by         session.<\/p>","href":"agent_cloud\/discover_observe_agent_cloud.html","attributes":{"data-id":"discover_observe_agent_cloud"},"menu":{"hasChildren":false},"tocID":"discover_observe_agent_cloud-d39307e63240","next":"discover_observe_agent_cloud-d39307e63240"},{"title":"Govern and control","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> policies are the governance rules that define the acceptable         behavior for your AI agents. Use them to detect risky activity and, on connections that         support it, stop it.<\/p>","href":"agent_cloud\/manage_agent_operations_policies.html","attributes":{"data-id":"manage_agent_operations_policies"},"menu":{"hasChildren":false},"tocID":"manage_agent_operations_policies-d39307e63433","next":"manage_agent_operations_policies-d39307e63433"},{"title":"Rewind agent actions","shortdesc":"<p class=\"shortdesc\">Agent Rewind undoes the changes that an agent action made to your data by restoring         the affected objects from Rubrik backups, without rolling back the entire workload. You can start a rewind from the Sessions page, or from any page that displays the action or         alert detail tray. Rewind requires a complete Rubrik snapshot taken within seven days         before the action.<\/p>","href":"agent_cloud\/rewind_agent_violations.html","attributes":{"data-id":"rewind_agent_violations"},"menu":{"hasChildren":false},"tocID":"rewind_agent_violations-d39307e63738","next":"rewind_agent_violations-d39307e63738"},{"title":"Administer Agent Cloud","shortdesc":"<p class=\"shortdesc\">Control who can view and manage <span class=\"ph\">Agent Cloud<\/span>, review platform and user         activity,  and follow best         practices for rollout and for building agents that are easier to govern.<\/p>","href":"agent_cloud\/administer_agent_cloud.html","attributes":{"data-id":"administer_agent_cloud"},"menu":{"hasChildren":false},"tocID":"administer_agent_cloud-d39307e63782","next":"administer_agent_cloud-d39307e63782"}]}};